using System;
using System.Diagnostics.CodeAnalysis;
using System.Runtime.CompilerServices;

namespace STS2RitsuLib.Utils;

/// <summary>
///     <para xml:lang="en">
///         Stores mod-attached state on arbitrary reference objects without subclassing or boxing through
///         object APIs.
///     </para>
///     <para xml:lang="zh-CN">在任意引用对象上存储模组附加状态，无需子类化，也无需通过 object API 装箱。</para>
/// </summary>
/// <remarks>
///     <para xml:lang="en">Entries follow the key object's lifetime. Callers must explicitly clear state when a live key is reused for a new combat, run, or UI binding.</para>
///     <para xml:lang="zh-CN">条目随键对象的生命周期保留。仍存活的键被复用于新战斗、新游戏或新界面绑定时，调用方必须显式清理状态。</para>
/// </remarks>
/// <param name="valueFactory">
///     <para xml:lang="en">Optional per-key factory; when null, lazily created values use <c>default(TValue)</c>.</para>
///     <para xml:lang="zh-CN">可选的按键工厂；为 null 时，惰性创建的值使用 <c>default(TValue)</c>。</para>
/// </param>
[TypeForwardedFrom("STS2-RitsuLib.Runtime, Version=0.6.2.0, Culture=neutral, PublicKeyToken=null")]
public sealed class AttachedState<TKey, TValue> where TKey : class
{
	private sealed class Box(TValue value)
	{
		public TValue Value { get; } = value;
	}

	private readonly ConditionalWeakTable<TKey, Box> _table = new ConditionalWeakTable<TKey, Box>();

	private readonly Func<TKey, TValue> _valueFactory = valueFactory ?? ((Func<TKey, TValue>)((TKey _) => default(TValue)));

	/// <summary>
	///     <para xml:lang="en">Gets or sets the attached value for <paramref name="key" />.</para>
	///     <para xml:lang="zh-CN">获取或设置 <paramref name="key" /> 的附加值。</para>
	/// </summary>
	public TValue this[TKey key]
	{
		get
		{
			return GetOrCreate(key);
		}
		set
		{
			Set(key, value);
		}
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Stores mod-attached state on arbitrary reference objects without subclassing or boxing through
	///         object APIs.
	///     </para>
	///     <para xml:lang="zh-CN">在任意引用对象上存储模组附加状态，无需子类化，也无需通过 object API 装箱。</para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">Entries follow the key object's lifetime. Callers must explicitly clear state when a live key is reused for a new combat, run, or UI binding.</para>
	///     <para xml:lang="zh-CN">条目随键对象的生命周期保留。仍存活的键被复用于新战斗、新游戏或新界面绑定时，调用方必须显式清理状态。</para>
	/// </remarks>
	/// <param name="valueFactory">
	///     <para xml:lang="en">Optional per-key factory; when null, lazily created values use <c>default(TValue)</c>.</para>
	///     <para xml:lang="zh-CN">可选的按键工厂；为 null 时，惰性创建的值使用 <c>default(TValue)</c>。</para>
	/// </param>
	public AttachedState(Func<TKey, TValue>? valueFactory)
	{
	}

	/// <summary>
	///     <para xml:lang="en">Creates state storage using an optional parameterless factory for default values.</para>
	///     <para xml:lang="zh-CN">使用可选的无参工厂创建具有默认值的状态存储。</para>
	/// </summary>
	public AttachedState(Func<TValue>? defaultValueFactory = null)
		: this((Func<TKey, TValue>?)((TKey _) => (defaultValueFactory == null) ? default(TValue) : defaultValueFactory()))
	{
	}

	/// <summary>
	///     <para xml:lang="en">Determines whether an entry exists for <paramref name="key" /> without creating one.</para>
	///     <para xml:lang="zh-CN">确定 <paramref name="key" /> 是否存在条目，但不创建条目。</para>
	/// </summary>
	public bool ContainsKey(TKey key)
	{
		ArgumentNullException.ThrowIfNull(key, "key");
		Box value;
		return _table.TryGetValue(key, out value);
	}

	/// <summary>
	///     <para xml:lang="en">Adds an entry for <paramref name="key" /> if absent.</para>
	///     <para xml:lang="zh-CN">如果 <paramref name="key" /> 缺少条目，则添加条目。</para>
