using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using MegaCrit.Sts2.Core.Models;

namespace STS2RitsuLib.Models.Capabilities;

/// <summary>
///     <para xml:lang="en">Registry for capability ids and factories.</para>
///     <para xml:lang="zh-CN">能力 ID 与工厂的注册表。</para>
/// </summary>
public static class ModelCapabilityRegistry
{
	private static readonly Lock SyncRoot = new Lock();

	private static readonly Dictionary<string, Func<IModelCapability>> Factories = new Dictionary<string, Func<IModelCapability>>(StringComparer.Ordinal);

	private static readonly Dictionary<string, Type> TypesById = new Dictionary<string, Type>(StringComparer.Ordinal);

	private static readonly Dictionary<Type, string> TypeIds = new Dictionary<Type, string>();

	/// <summary>
	///     <para xml:lang="en">Registers or replaces a capability factory.</para>
	///     <para xml:lang="zh-CN">注册或替换能力工厂。</para>
	/// </summary>
	public static void Register(string capabilityId, Type capabilityType, Func<IModelCapability> factory)
	{
		ArgumentException.ThrowIfNullOrWhiteSpace(capabilityId, "capabilityId");
		ArgumentNullException.ThrowIfNull(capabilityType, "capabilityType");
		ArgumentNullException.ThrowIfNull(factory, "factory");
		if (capabilityType.ContainsGenericParameters || !typeof(IModelCapability).IsAssignableFrom(capabilityType))
		{
			throw new ArgumentException("Capability type must be closed and implement IModelCapability.", "capabilityType");
		}
		using (SyncRoot.EnterScope())
		{
			if (TypesById.TryGetValue(capabilityId, out Type value) && value != capabilityType)
			{
				throw new InvalidOperationException("Model capability id is already registered for '" + value.FullName + "': " + capabilityId);
			}
			if (TypeIds.TryGetValue(capabilityType, out string value2) && !string.Equals(value2, capabilityId, StringComparison.Ordinal))
			{
				throw new InvalidOperationException("Model capability id is already registered: " + capabilityId);
			}
			Factories[capabilityId] = factory;
			TypesById[capabilityId] = capabilityType;
			TypeIds[capabilityType] = capabilityId;
		}
	}

	/// <summary>
	///     <para xml:lang="en">Registers a capability factory.</para>
	///     <para xml:lang="zh-CN">注册能力工厂。</para>
	/// </summary>
	public static void Register<TCapability>(string capabilityId, Func<TCapability> factory) where TCapability : IModelCapability
	{
		ArgumentNullException.ThrowIfNull(factory, "factory");
		Register(capabilityId, typeof(TCapability), () => factory());
	}

	/// <summary>
	///     <para xml:lang="en">Registers a parameterless capability factory.</para>
	///     <para xml:lang="zh-CN">注册无参能力工厂。</para>
	/// </summary>
	public static void Register<TCapability>(string capabilityId) where TCapability : IModelCapability, new()
	{
		Register(capabilityId, () => new TCapability());
	}

	/// <summary>
	///     <para xml:lang="en">Creates a capability by ID.</para>
	///     <para xml:lang="zh-CN">通过 ID 创建能力。</para>
	/// </summary>
	public static bool TryCreate(string capabilityId, out IModelCapability capability)
	{
		Func<IModelCapability> value;
		Type value2;
		using (SyncRoot.EnterScope())
		{
			if (!Factories.TryGetValue(capabilityId, out value) || !TypesById.TryGetValue(capabilityId, out value2))
			{
				capability = null;
				return false;
			}
		}
		capability = value() ?? throw new InvalidOperationException("Model capability factory returned null: " + capabilityId);
		if (!value2.IsInstanceOfType(capability))
		{
			throw new InvalidOperationException($"Model capability factory for '{capabilityId}' returned '{capability.GetType().FullName}', which is not assignable to '{value2.FullName}'.");
		}
		if (!string.Equals(capability.CapabilityId, capabilityId, StringComparison.Ordinal))
		{
			throw new InvalidOperationException($"Model capability factory for '{capabilityId}' returned a capability with id '{capability.CapabilityId}'.");
		}
		return true;
	}

	/// <summary>
	///     <para xml:lang="en">Creates a capability by registered type, if a matching factory exists.</para>
	///     <para xml:lang="zh-CN">按已注册类型创建能力（如果存在匹配工厂）。</para>
	/// </summary>
	public static bool TryCreate<TCapability>(out TCapability capability) where TCapability : class, IModelCapability
	{
		string capabilityId = GetCapabilityId<TCapability>();
		if (capabilityId == null || !TryCreate(capabilityId, out IModelCapability capability2) || !(capability2 is TCapability val))
		{
			capability = null;
			return false;
		}
		capability = val;
		return true;
	}

	/// <summary>
	///     <para xml:lang="en">Creates a capability by ID or throws when no factory is registered.</para>
	///     <para xml:lang="zh-CN">通过 ID 创建能力；未注册工厂时抛出异常。</para>
	/// </summary>
	public static IModelCapability Create(string capabilityId)
	{
		if (!TryCreate(capabilityId, out IModelCapability capability))
		{
			throw new InvalidOperationException("Model capability id is not registered: " + capabilityId);
		}
		return capability;
	}

	/// <summary>
	///     <para xml:lang="en">Creates a capability by registered type or throws when no matching factory is registered.</para>
	///     <para xml:lang="zh-CN">按已注册类型创建能力；未注册匹配工厂时抛出异常。</para>
	/// </summary>
	public static TCapability Create<TCapability>() where TCapability : class, IModelCapability
	{
		string capabilityId = GetCapabilityId<TCapability>();
		if (capabilityId == null)
		{
			throw new InvalidOperationException("Model capability type is not registered: " + typeof(TCapability).FullName);
		}
		return (Create(capabilityId) as TCapability) ?? throw new InvalidOperationException($"Registered capability '{capabilityId}' is not a '{typeof(TCapability).FullName}'.");
	}

	/// <summary>
	///     <para xml:lang="en">Gets the registered capability ID for a capability type, if any.</para>
	///     <para xml:lang="zh-CN">获取能力类型已注册的能力 ID（如果存在）。</para>
	/// </summary>
	public static string? GetCapabilityId(Type capabilityType)
	{
		ArgumentNullException.ThrowIfNull(capabilityType, "capabilityType");
		using (SyncRoot.EnterScope())
		{
			return TypeIds.GetValueOrDefault(capabilityType);
		}
	}

	/// <summary>
	///     <para xml:lang="en">Gets the registered capability ID for <typeparamref name="TCapability" />, if any.</para>
	///     <para xml:lang="zh-CN">获取 <typeparamref name="TCapability" /> 已注册的能力 ID（如果存在）。</para>
	/// </summary>
	public static string? GetCapabilityId<TCapability>() where TCapability : IModelCapability
	{
		return GetCapabilityId(typeof(TCapability));
	}

	/// <summary>
	///     <para xml:lang="en">Attempts to resolve the capability type registered for <paramref name="capabilityId" />.</para>
	///     <para xml:lang="zh-CN">尝试解析 <paramref name="capabilityId" /> 注册的能力类型。</para>
	/// </summary>
	public static bool TryGetCapabilityType(string capabilityId, out Type capabilityType)
	{
		ArgumentException.ThrowIfNullOrWhiteSpace(capabilityId, "capabilityId");
		using (SyncRoot.EnterScope())
		{
			return TypesById.TryGetValue(capabilityId, out capabilityType);
		}
	}

	internal static IReadOnlyList<ModelCapabilityRegistration> GetRegistrationsSnapshot()
	{
		using (SyncRoot.EnterScope())
		{
			return Array.AsReadOnly(TypesById.Select<KeyValuePair<string, Type>, ModelCapabilityRegistration>((KeyValuePair<string, Type> pair) => new ModelCapabilityRegistration(pair.Key, pair.Value)).OrderBy<ModelCapabilityRegistration, string>((ModelCapabilityRegistration registration) => registration.Id, StringComparer.Ordinal).ToArray());
		}
	}

	internal static bool IsCompatibleWith(Type capabilityType, AbstractModel owner)
	{
		ArgumentNullException.ThrowIfNull(capabilityType, "capabilityType");
		ArgumentNullException.ThrowIfNull(owner, "owner");
		Type[] array = (from candidate in capabilityType.GetInterfaces()
			where candidate.IsGenericType && candidate.GetGenericTypeDefinition() == typeof(IModelCapability<>)
			select candidate.GetGenericArguments()[0]).Distinct().ToArray();
		if (array.Length != 0)
		{
			return array.Any((Type ownerType) => ownerType.IsInstanceOfType(owner));
		}
		return true;
	}

	internal static void RegisterModelCapability(Type capabilityType, string capabilityId)
	{
		if (!typeof(ModelCapability).IsAssignableFrom(capabilityType))
		{
			throw new ArgumentException("Capability type must inherit ModelCapability.", "capabilityType");
		}
		Register(capabilityId, capabilityType, () => (IModelCapability)ModelDb.Get(capabilityType).MutableClone());
	}

	internal static string GetModelCapabilityId(Type capabilityType)
	{
		return GetCapabilityId(capabilityType) ?? throw new InvalidOperationException("Model capability type is not registered: " + capabilityType.FullName);
	}
}
